61	// Check if operation is a view operation (zero-copy metadata transform).
62	// A view op is one registered with set_output_memory_inherit_input() — its
63	// output reuses the input's MemRef view. Delegates to the shared registry
64	// predicate so InferTileMemorySpace and InitMemRef agree on the set.
65	bool IsViewOperation(const std::string& op_name) {
66	  auto& registry = OpRegistry::GetInstance();
67	  if (!registry.IsRegistered(op_name)) return false;
68	  return registry.GetEntry(op_name).OutputMemoryInheritsInput();
69	}
70	
71	// Whether an inherit-input op *permutes* data rather than just reinterpreting
72	// it (tile.transpose).  A pure metadata view (slice/reshape/extract/...) aliases
73	// its input's buffer, but a permuting op's output must never alias the input:
74	// pto.ttrans is not in-place safe (the unaligned scalar path writes dst directly
75	// from src), so InitMemRef gives the transpose output a fresh buffer.
76	bool IsDataPermutingInheritOp(const OpPtr& op) { return IsOp(op, "tile.transpose"); }
77	
78	// A tile owns no general-pool buffer ("buffer-less by design") when its defining
79	// value is a cross-core tpop result, or a non-permuting zero-copy view / plain
80	// alias chained off a buffer-less source. `source_buffer_less` reports whether a
81	// source Var is itself buffer-less (the MemRef-creating mutator queries the type;
82	// the HasMemRefs verifier consults its tracked set). tile.transpose is excluded —
83	// pto.ttrans is not in-place safe and always needs a fresh buffer.
84	template <typename SourceBufferLess>
85	bool ProducesBufferLessTile(const ExprPtr& value, const SourceBufferLess& source_buffer_less) {
86	  if (auto call = std::dynamic_pointer_cast<const Call>(value)) {
87	    if (!call->op_) return false;
88	    if (IsOp(call, "tile.tpop_from_aic") || IsOp(call, "tile.tpop_from_aiv")) {
89	      return true;
90	    }
91	    if (op_predicates::IsBufferAliasingViewOp(call->op_->name_) && !call->args_.empty()) {
92	      auto in = AsVarLike(call->args_[0]);
93	      return in && source_buffer_less(in.get());
94	    }
95	    return false;
96	  }
97	  auto v = AsVarLike(value);
98	  return v && source_buffer_less(v.get());
99	}
