101	// Check if an operation's output should reuse the MemRef of a specific input argument.
102	// Returns the input arg index whose MemRef to share, or nullopt.
103	std::optional<size_t> GetOutputReusesInputArg(const std::string& op_name) {
104	  auto& registry = OpRegistry::GetInstance();
105	  if (!registry.IsRegistered(op_name)) return std::nullopt;
106	  return registry.GetEntry(op_name).GetOutputReusesInputArg();
107	}
