109	/// Byte envelope touched by a static packed slice, relative to its first
110	/// element. This is deliberately distinct from the physical allocation size:
111	/// L0C row padding belongs to the root allocation and must not be applied again
112	/// to a view beginning part-way through that allocation.
113	std::optional<uint64_t> StaticSliceViewSpanBytes(const CallPtr& call, const ShapedTypePtr& parent,
114	                                                 const ShapedTypePtr& view) {
115	  if (!call || (!IsOp(call, "tensor.slice") && !IsOp(call, "tile.slice"))) return std::nullopt;
116	  if (!parent || !view || call->args_.size() < 2) return std::nullopt;
117	  // Use the requested pre-drop shape rather than the result rank so
118	  // tile.slice(..., drop_dims=...) keeps the parent strides of dimensions that
119	  // disappear from the result type.
120	  auto requested_shape = As<MakeTuple>(call->args_[1]);
121	  if (!requested_shape || parent->shape_.size() != requested_shape->elements_.size()) {
122	    return std::nullopt;
123	  }
124	
125	  uint64_t max_linear_offset = 0;
126	  uint64_t stride = 1;
127	  for (size_t rev = 0; rev < parent->shape_.size(); ++rev) {
128	    const size_t i = parent->shape_.size() - 1 - rev;
129	    auto parent_dim = As<ConstInt>(parent->shape_[i]);
130	    auto view_dim = As<ConstInt>(requested_shape->elements_[i]);
131	    if (!parent_dim || !view_dim || parent_dim->value_ <= 0 || view_dim->value_ <= 0 ||
132	        view_dim->value_ > parent_dim->value_) {
133	      return std::nullopt;
134	    }
135	
136	    const uint64_t parent_extent = static_cast<uint64_t>(parent_dim->value_);
137	    const uint64_t view_extent = static_cast<uint64_t>(view_dim->value_);
138	    if (view_extent - 1 > std::numeric_limits<uint64_t>::max() / stride) return std::nullopt;
139	    const uint64_t contribution = (view_extent - 1) * stride;
140	    if (max_linear_offset > std::numeric_limits<uint64_t>::max() - contribution) return std::nullopt;
141	    max_linear_offset += contribution;
142	    if (rev + 1 < parent->shape_.size()) {
143	      if (stride > std::numeric_limits<uint64_t>::max() / parent_extent) return std::nullopt;
144	      stride *= parent_extent;
145	    }
146	  }
147	
148	  if (max_linear_offset == std::numeric_limits<uint64_t>::max()) return std::nullopt;
149	  return storage_size::StaticStorageBytes(max_linear_offset + 1, view->dtype_);
150	}
