152	// ============================================================================
153	// Author-declared allocations (`pl.Tile[..., pl.MemRef("name"), ...]`)
154	// ============================================================================
155	
156	/// Slot geometry derived for one declared allocation.
157	struct DeclaredAlloc {
158	  uint64_t slot_size = 0;  ///< Bytes per slot — the largest tile bound to any slot
159	  /// How many slots the author declared; 0 until the first binding records it.
160	  /// The sentinel must be a value a real declaration can never carry — 1 would
161	  /// collide with an ordinary unsubscripted declaration, and a later, genuinely
162	  /// different count would then overwrite it instead of tripping the mismatch
163	  /// check. `Record` rejects anything below 1, so 0 is safe.
164	  uint64_t slot_count = 0;
165	
166	  /// Total bytes to allocate: every slot is the same size and they sit contiguously,
167	  /// which is what makes `slot_index * slot_size` a valid offset.
168	  ///
169	  /// Both factors are author-controlled (`slots=N` and the bound tile's shape), so
170	  /// the product is checked rather than assumed: wrapping would turn an absurd
171	  /// request into a *small* allocation and hand out addresses inside it.
172	  [[nodiscard]] uint64_t TotalSize() const {
173	    CHECK(slot_count == 0 || slot_size <= std::numeric_limits<uint64_t>::max() / slot_count)
174	        << "Declared allocation is too large: " << slot_count << " slots of " << slot_size
175	        << " bytes overflows a 64-bit size";
176	    return slot_size * slot_count;
177	  }
178	};
179	
180	/// Base Ptr of a declared allocation -> its slot geometry.
181	using DeclaredAllocMap = std::map<const Var*, DeclaredAlloc>;
182	
183	/// The declared-allocation MemRef `type` carries, or null when it carries none.
184	///
185	/// `MemRef::is_pinned_` is what tells an author's declaration apart from a
186	/// compiler allocation: re-parsing a post-allocation dump also puts MemRefs on
187	/// TileTypes, and those are the compiler's. Keying on an explicit field rather
188	/// than on "we are standing before InitMemRef" keeps the classification a
189	/// property of the data, so a dump can be reparsed and re-run without its
190	/// allocations turning into declared ones.
191	///
192	/// Returning the MemRef (not just its base) spares every caller a second,
193	/// unchecked unwrap of the same optional.
194	MemRefPtr GetDeclaredAlloc(const TypePtr& type) {
195	  auto tile_type = As<TileType>(type);
196	  if (!tile_type || !tile_type->memref_.has_value()) return nullptr;
197	  const auto& memref = *tile_type->memref_;
198	  if (!memref->base_ || !memref->is_pinned_) return nullptr;
199	  return memref;
200	}
201	
202	/// Collect every declared allocation in a function, deriving each one's size
203	/// (the largest bound tile) and checking the bound tiles agree on memory space.
204	class DeclaredAllocCollector : public IRVisitor {
205	 public:
206	  explicit DeclaredAllocCollector(const backend::BackendHandler* handler) : handler_(handler) {}
207	
208	  DeclaredAllocMap buffers;
209	
210	  // Every binding reaches this pass on a Var's type, so one VarLike override
211	  // covers assignment LHSs and iter_args alike. Parameters are NOT visited —
212	  // the traversal starts at the body — which is sound because the parser refuses
213	  // a one-argument `pl.MemRef(...)` in a parameter annotation, so no declaration
214	  // can arrive on a param.
215	  void VisitVarLike_(const VarPtr& op) override {
216	    if (op) Record(op);
217	    IRVisitor::VisitVarLike_(op);
218	  }
219	
220	 private:
221	  void Record(const VarPtr& var) {
222	    auto binding = GetDeclaredAlloc(var->GetType());
223	    if (!binding) return;
224	    const VarPtr& base = binding->base_;
225	    auto tile_type = As<TileType>(var->GetType());
226	
227	    const MemorySpace space = tile_type->GetMemorySpace().value_or(MemorySpace::DDR);
228	    auto size = utils::StaticPhysicalAllocationBytes(tile_type, space, handler_);
229	    CHECK_SPAN(size.has_value(), var->span_)
230	        << "Tile '" << var->name_hint_ << "' is bound to the declared allocation '" << base->name_hint_
231	        << "' but has a dynamic shape; a declared allocation must be sized at compile time";
232	
233	    auto& alloc = buffers[base.get()];
234	    // One slot must hold the largest tile bound to ANY slot: the slots are
235	    // uniform, so a per-slot size would make the stride inconsistent.
236	    alloc.slot_size = std::max(alloc.slot_size, *size);
237	
238	    CHECK_SPAN(binding->slot_count_ >= 1, var->span_)
239	        << "Declared allocation '" << base->name_hint_ << "' must have at least one slot, got "
240	        << binding->slot_count_;
241	    if (alloc.slot_count == 0) {
242	      alloc.slot_count = binding->slot_count_;
243	    }
244	    CHECK_SPAN(alloc.slot_count == binding->slot_count_, var->span_)
245	        << "References to the declared allocation '" << base->name_hint_
246	        << "' disagree on how many slots it has (" << alloc.slot_count << " vs " << binding->slot_count_
247	        << "); one declaration has one slot count";
248	
249	    if (tile_type->memory_space_.has_value()) {
250	      auto [it, inserted] = spaces_.emplace(base.get(), *tile_type->memory_space_);
251	      CHECK_SPAN(inserted || it->second == *tile_type->memory_space_, var->span_)
252	          << "Tiles bound to the declared allocation '" << base->name_hint_
253	          << "' must all live in the same memory space, but '" << var->name_hint_ << "' is "
254	          << MemorySpaceToString(*tile_type->memory_space_) << " while the allocation is already "
255	          << MemorySpaceToString(it->second);
256	    }
257	  }
258	
259	  const backend::BackendHandler* handler_ = nullptr;
260	  std::map<const Var*, MemorySpace> spaces_;
261	};
