263	// Mutator to initialize MemRef for variables
264	class InitMemRefMutator : public IRMutator {
265	 public:
266	  InitMemRefMutator(const DeclaredAllocMap& declared_allocs, const backend::BackendHandler* handler,
267	                    FunctionType func_type)
268	      : declared_allocs_(declared_allocs), handler_(handler), func_type_(func_type) {}
269	
270	  /// Whether `type` is bound to one of this function's declared allocations.
271	  [[nodiscard]] bool HasUserBinding(const TypePtr& type) const {
272	    if (declared_allocs_.empty()) return false;
273	    auto binding = GetDeclaredAlloc(type);
274	    return binding && declared_allocs_.count(binding->base_.get()) > 0;
275	  }
276	
277	  /// The MemRef a user binding asks for, sized to the slot it selects.
278	  /// Returns nullopt when `type` carries no binding.
279	  std::optional<MemRefPtr> UserBoundMemRef(const TypePtr& type) const {
280	    if (declared_allocs_.empty()) return std::nullopt;
281	    auto binding = GetDeclaredAlloc(type);
282	    if (!binding) return std::nullopt;
283	    auto it = declared_allocs_.find(binding->base_.get());
284	    if (it == declared_allocs_.end()) return std::nullopt;
285	    // Every bound tile gets the SAME base Ptr — that shared identity is what
286	    // makes them share storage — and the slot index becomes the byte offset:
287	    // `index * slot_size`. A constant index folds here, so a single-slot or
288	    // constant-slot declaration keeps the ConstInt offset every downstream pass
289	    // already expects. A runtime index survives as an expression that
290	    // AllocateMemoryAddr adds the base address to and codegen lowers into the
291	    // tile's address assignment.
292	    //
293	    // Size is ONE SLOT, not the whole allocation: `size_` is the extent of the
294	    // region this MemRef denotes, and `[offset, offset + size_)` is the range
295	    // `MayAlias` intersects and the address verifier bounds-checks. Sizing a slot
296	    // to the whole set would make slot 1 of two span `[S, 3S)` — overrunning the
297	    // allocation for the verifier, and overlapping slot 0 for MayAlias, which
298	    // would report the ping-pong's two halves as aliasing. The allocation itself
299	    // is sized to the full set separately, where the alloc statement is built.
300	    //
301	    // The slot geometry rides along on the resolved MemRef. Resolving the index
302	    // into an offset answers *where* the slot lands; it does not stop the MemRef
303	    // from being slot k of an N-slot allocation, and that is what lets PTO codegen
304	    // emit `pto.alloc_multi_tile` / `pto.multi_tile_get` instead of N unrelated
305	    // allocs. `is_pinned_` still clears here: the declaration is resolved, and the
306	    // flag is what confines MemRef rebuilds to the pre-InitMemRef window.
307	    return std::make_shared<MemRef>(binding->base_, SlotByteOffset(*binding, it->second),
308	                                    it->second.slot_size, Span::unknown(), /*is_pinned=*/false,
309	                                    binding->slot_count_, binding->slot_index_);
310	  }
311	
312	  /// The byte offset a declaration's slot index denotes, folded when constant.
313	  ///
314	  /// Returns `binding`'s own offset untouched for an unsubscripted declaration —
315	  /// there is no slot arithmetic to do, and slot 0 of a 1-slot allocation is the
316	  /// allocation itself.
317	  static ExprPtr SlotByteOffset(const MemRef& binding, const DeclaredAlloc& alloc) {
318	    if (!binding.slot_index_.has_value() || !*binding.slot_index_) return binding.byte_offset_;
319	    const ExprPtr& slot_index = *binding.slot_index_;
320	    const auto& span = binding.span_;
321	    if (auto const_index = As<ConstInt>(slot_index)) {
322	      return std::make_shared<ConstInt>(
323	          static_cast<int64_t>(static_cast<uint64_t>(const_index->value_) * alloc.slot_size), DataType::INT64,
324	          span);
325	    }
326	    // INDEX for the runtime product: the index comes from loop variables, which are
327	    // INDEX-typed, and the existing dynamic-offset expressions (tile.slice views)
328	    // are built the same way. Codegen widens to the i64 the PTOAS `alloc_tile` addr
329	    // operand wants when it lowers the address.
330	    auto stride = std::make_shared<ConstInt>(static_cast<int64_t>(alloc.slot_size), DataType::INDEX, span);
331	    return std::make_shared<Mul>(slot_index, stride, DataType::INDEX, span);
332	  }
333	
334	  // Resolve memory space from TileType::memory_space_ field (set by InferTileMemorySpace),
335	  // falling back to DDR when default_to_ddr is true.
336	  [[nodiscard]] static std::optional<MemorySpace> ResolveTileMemorySpace(const TypePtr& type,
337	                                                                         bool default_to_ddr = false) {
338	    if (auto tile_type = std::dynamic_pointer_cast<const TileType>(type)) {
339	      if (tile_type->memory_space_.has_value()) {
340	        return tile_type->memory_space_;
341	      }
342	    }
343	
344	    if (default_to_ddr) {
345	      return MemorySpace::DDR;
346	    }
347	    return std::nullopt;
348	  }
349	
350	  // Calculate allocation size and create MemRef with the given memory space.
351	  std::optional<MemRefPtr> CreateMemRef(const ShapedTypePtr& type, const VarPtr& var,
352	                                        std::optional<MemorySpace> memory_space) {
353	    const std::string var_name = var ? var->name_hint_ : "<anonymous>";
354	    const Span& err_span = var ? var->span_ : Span::unknown();
355	    INTERNAL_CHECK_SPAN(memory_space.has_value(), err_span)
356	        << "Internal error: memory_space must be resolved before CreateMemRef";
357	
358	    if (As<TileType>(type)) {
359	      for (size_t i = 0; i < type->shape_.size(); ++i) {
360	        auto const_dim = As<ConstInt>(type->shape_[i]);
361	        INTERNAL_CHECK_SPAN(const_dim, err_span)
362	            << "InitMemRef requires static shape for variable '" << var_name << "', but shape element " << i
363	            << " is dynamic. Fix the upstream op to keep TileType.shape static and put runtime "
364	               "extent in TileView.valid_shape instead.";
365	        INTERNAL_CHECK_SPAN(const_dim->value_ > 0, err_span)
366	            << "InitMemRef requires positive shape for variable '" << var_name << "', but shape element " << i
367	            << " is " << const_dim->value_;
368	      }
369	    }
370	
371	    auto static_size = utils::StaticPhysicalAllocationBytes(type, *memory_space, handler_);
372	    INTERNAL_CHECK_SPAN(!As<TileType>(type) || static_size.has_value(), err_span)
373	        << "InitMemRef cannot represent the physical allocation size for static tile variable '" << var_name
374	        << "' without overflowing 64-bit bytes";
375	    const uint64_t size_bytes = static_size.value_or(0);
376	
377	    auto base =
378	        std::make_shared<Var>(BuildBasePtrName(*memory_space, next_id_++), GetPtrType(), Span::unknown());
379	    return std::make_shared<MemRef>(base, static_cast<int64_t>(0), size_bytes);
380	  }
381	
382	  std::optional<MemorySpace> ExtractMemorySpaceFromType(const TypePtr& type) {
383	    auto shaped_type = std::dynamic_pointer_cast<const ShapedType>(type);
384	    if (!shaped_type) {
385	      return std::nullopt;
386	    }
387	    return shaped_type->GetMemorySpace();
388	  }
389	
390	  // Process IterArg variable (inherits MemRef from initValue)
391	  VarPtr ProcessIterArg(const VarPtr& old_var) {
392	    auto iter_arg = std::static_pointer_cast<const IterArg>(old_var);
393	
394	    // Visit initValue to get its updated MemRef
395	    auto new_init = VisitExpr(iter_arg->initValue_);
396	
397	    // Extract MemRef from initValue and create new type
398	    auto memref = GetTypeMemRef(new_init->GetType());
399	    auto old_var_expr = std::static_pointer_cast<const Expr>(old_var);
400	    auto source_memory_space = ExtractMemorySpaceFromType(new_init->GetType());
401	    TypePtr new_type = CloneTypeWithMemRefAndRemapExprs(
402	        old_var_expr->GetType(), memref, [this](const ExprPtr& expr) { return VisitExpr(expr); },
403	        source_memory_space);
404	
405	    return std::make_shared<IterArg>(iter_arg->name_hint_, new_type, new_init, iter_arg->span_);
406	  }
407	
408	  // Process normal Var variable (creates new MemRef based on usage)
409	  VarPtr ProcessNormalVar(const VarPtr& var) {
410	    auto var_expr = std::static_pointer_cast<const Expr>(var);
411	    TypePtr new_type = var_expr->GetType();
412	
413	    // ArrayType lives on the on-core scalar register file / C stack and never
414	    // needs a runtime MemRef — codegen lowers it to a stack array directly.
415	    // Leave the var untouched so the original ArrayType (no memref_) propagates.
416	    if (std::dynamic_pointer_cast<const ArrayType>(var_expr->GetType())) {
417	      return var;
418	    }
419	
420	    if (auto shaped_type = std::dynamic_pointer_cast<const ShapedType>(var_expr->GetType())) {
421	      // A tile must already have its space: InitMemRef declares
422	      // IRProperty::TileMemoryInferred as required, so an unset one here means
423	      // InferTileMemorySpace did not cover this function. Defaulting it to DDR
424	      // instead produced a "tile" in global memory that later reads as a real
425	      // placement -- a vector op with a DDR operand, and a memory planner
426	      // packing every such tile at offset 0. Fail with the tile's name rather
427	      // than let that travel. Non-tile ShapedTypes (tensors) keep the DDR
428	      // default, which is their correct home.
429	      if (auto tile_type = std::dynamic_pointer_cast<const TileType>(var_expr->GetType())) {
430	        if (IsInCoreType(func_type_)) {
431	          // A device tile with no space after pass 17 is a compiler bug:
432	          // InferTileMemorySpace covers every IsInCoreType function and is
433	          // declared to produce TileMemoryInferred.
434	          INTERNAL_CHECK_SPAN(tile_type->memory_space_.has_value(), var->span_)
435	              << "Internal error: tile '" << var->name_hint_
436	              << "' reached InitMemRef with no memory space; InferTileMemorySpace must place every "
437	                 "tile in a device function before this pass runs";
438	        } else {
439	          // Outside a device function there is no on-chip buffer for a tile to
440	          // live in, so no space can be inferred and none should be defaulted
441	          // -- the old DDR fallback produced a "tile" in global memory that
442	          // later read as a real placement. This is an authoring error, not a
443	          // compiler bug: tile ops belong in a device function.
444	          CHECK_SPAN(tile_type->memory_space_.has_value(), var->span_)
445	              << "The tile '" << var->name_hint_ << "' lives in a " << FunctionTypeToString(func_type_)
446	              << " function, which has no on-chip memory to place it in. Tiles are on-chip "
447	                 "hardware state, so tile ops belong in a device function -- move this code into "
448	                 "an InCore function, or into a pl.scope() the outliner turns into one.";
449	        }
450	      }
451	      // Resolve memory space once, pass to both CreateMemRef and CloneType
452	      auto memory_space = ResolveTileMemorySpace(var_expr->GetType(), /*default_to_ddr=*/true);
453	      // A declared allocation wins over a fresh one: the whole point is
454	      // that this tile lands in the buffer the kernel author named.
455	      auto memref = UserBoundMemRef(var_expr->GetType());
456	      if (!memref.has_value()) memref = CreateMemRef(shaped_type, var, memory_space);
457	      new_type = CloneTypeWithMemRefAndRemapExprs(
458	          var_expr->GetType(), memref, [this](const ExprPtr& expr) { return VisitExpr(expr); }, memory_space);
459	    } else {
460	      // Non-shaped types (e.g. ScalarType for dynamic-shape dimensions like M, N)
461	      // don't need MemRef initialization — return the original Var to preserve
462	      // pointer identity across all type annotations that reference it.
463	      return var;
464	    }
465	
466	    return std::make_shared<Var>(var->name_hint_, new_type, var->span_);
467	  }
468	
469	  // Create a new Var with MemRef initialized
470	  VarPtr GetNewVar(const VarPtr& old_var) {
471	    // Check cache first to prevent infinite recursion
472	    auto it = var_map_.find(old_var);
473	    if (it != var_map_.end()) {
474	      return it->second;
475	    }
476	
477	    // Dispatch based on variable type
478	    VarPtr new_var;
479	    if (std::dynamic_pointer_cast<const IterArg>(old_var)) {
480	      new_var = ProcessIterArg(old_var);
481	    } else {
482	      new_var = ProcessNormalVar(old_var);
483	    }
484	
485	    var_map_[old_var] = new_var;
486	    return new_var;
487	  }
488	
489	  ExprPtr VisitExpr_(const VarPtr& op) override {
490	    return std::static_pointer_cast<const Expr>(GetNewVar(op));
491	  }
492	
493	  ExprPtr VisitExpr_(const IterArgPtr& op) override {
494	    // IterArg extends Var, so cast to VarPtr for processing
495	    auto var_ptr = std::static_pointer_cast<const Var>(op);
496	    return std::static_pointer_cast<const Expr>(GetNewVar(var_ptr));
497	  }
498	
499	  /**
500	   * @brief Create a view MemRef from a source expression for the LHS variable of an assignment.
501	   *
502	   * Creates a NEW MemRef with the same base_ Ptr as the source's MemRef,
503	   * accumulated byte offset, and computed size from the output shape.
504	   * Returns nullptr if the source has no MemRef.
505	   */
506	  StmtPtr ShareMemRefFrom(const ExprPtr& source, const AssignStmtPtr& op, const ExprPtr& new_value) {
507	    auto parent_memref_opt = GetTypeMemRef(source->GetType());
508	    if (!parent_memref_opt.has_value()) return nullptr;
509	    const auto& parent_memref = *parent_memref_opt;
510	
511	    // Compute additional byte offset from the view op (if applicable)
512	    ExprPtr additional_offset = MakeZeroByteOffset();
513	    if (auto call = As<Call>(new_value)) {
514	      additional_offset = ComputeViewByteOffset(call, source->GetType());
515	    }
516	
517	    // Accumulate: total_offset = parent.byte_offset + additional_offset
518	    ExprPtr total_offset = AddByteOffsets(parent_memref->byte_offset_, additional_offset);
519	
520	    auto source_ms = ExtractMemorySpaceFromType(source->GetType());
521	
522	    // Keep ordinary aliases/reshapes at the parent's physical range. A slice
523	    // narrows that range to the packed parent-layout envelope it can touch.
524	    // Crucially, this is a VIEW span, not a fresh allocation footprint: an Acc
525	    // slice beginning at row 16 of a 32-row INT32 allocation must end at the
526	    // root boundary, not acquire another 32 rows of L0C padding.
527	    uint64_t view_size = parent_memref->size_;  // default: same size as parent
528	    if (auto call = As<Call>(new_value)) {
529	      auto parent_shaped = std::dynamic_pointer_cast<const ShapedType>(source->GetType());
530	      auto out_shaped = std::dynamic_pointer_cast<const ShapedType>(op->var_->GetType());
531	      if (auto slice_span = StaticSliceViewSpanBytes(call, parent_shaped, out_shaped)) {
532	        view_size = *slice_span;
533	      }
534	    }
535	
536	    // For pure aliases (no offset change, same size), share the SAME MemRef shared_ptr
537	    // to preserve base_ Ptr identity. MemoryReuse builds sharing groups by base_ Ptr —
538	    // variables sharing the same base_ are merged into one lifetime group.
539	    bool is_pure_alias = (view_size == parent_memref->size_);
540	    if (is_pure_alias) {
541	      if (auto const_offset = As<ConstInt>(additional_offset)) {
542	        is_pure_alias = (const_offset->value_ == 0);
543	      } else {
544	        is_pure_alias = false;
545	      }
546	    }
547	    MemRefPtr view_memref = is_pure_alias
548	                                ? parent_memref
549	                                : std::make_shared<MemRef>(parent_memref->base_, total_offset, view_size);
550	
551	    std::optional<MemRefPtr> view_opt = view_memref;
552	    TypePtr new_type = CloneTypeWithMemRefAndRemapExprs(
553	        op->var_->GetType(), view_opt, [this](const ExprPtr& e) { return VisitExpr(e); }, source_ms);
554	    VarPtr new_var = std::make_shared<Var>(op->var_->name_hint_, new_type, op->var_->span_);
555	    var_map_[op->var_] = new_var;
556	    return std::make_shared<AssignStmt>(new_var, new_value, op->span_);
557	  }
558	
559	  // Rebuild an AssignStmt whose LHS tile var keeps its TileType + memory_space but
560	  // carries no MemRef. Used for tiles that own no general-pool buffer: cross-core
561	  // tpop results and zero-copy views over them (codegen lowers those to
562	  // pto.treshape over the source rather than a fresh alloc_tile).
563	  StmtPtr MakeMemRefLessAssign(const AssignStmtPtr& op, const ExprPtr& new_value) {
564	    auto var_expr = std::static_pointer_cast<const Expr>(op->var_);
565	    if (auto tile_type = std::dynamic_pointer_cast<const TileType>(var_expr->GetType())) {
566	      for (size_t i = 0; i < tile_type->shape_.size(); ++i) {
567	        INTERNAL_CHECK_SPAN(As<ConstInt>(tile_type->shape_[i]), op->var_->span_)
568	            << "InitMemRef requires static shape for variable '" << op->var_->name_hint_
569	            << "', but shape element " << i
570	            << " is dynamic. Fix the upstream op to keep TileType.shape static and put runtime "
571	               "extent in TileView.valid_shape instead.";
572	      }
573	    }
574	    TypePtr new_type = CloneTypeWithMemRefAndRemapExprs(
575	        var_expr->GetType(), std::nullopt, [this](const ExprPtr& expr) { return VisitExpr(expr); },
576	        ResolveTileMemorySpace(var_expr->GetType()));
577	    auto new_var = std::make_shared<Var>(op->var_->name_hint_, new_type, op->var_->span_);
578	    var_map_[op->var_] = new_var;
579	    return std::make_shared<AssignStmt>(new_var, new_value, op->span_);
580	  }
581	
582	  StmtPtr VisitStmt_(const AssignStmtPtr& op) override {
583	    // First visit the value (RHS)
584	    auto new_value = VisitExpr(op->value_);
585	
586	    // A tile that owns no general-pool buffer — a cross-core tpop result (its
587	    // data lives in the reserved C2V/V2C slot, addressed via the pipe), or a
588	    // zero-copy view / plain alias chained off one — stays MemRef-less, so
589	    // AllocateMemoryAddr reserves no phantom buffer and no fresh, disconnected
590	    // buffer is created.
591	    if (As<TileType>(op->var_->GetType()) && ProducesBufferLessTile(new_value, [](const Var* v) {
592	          return !GetTypeMemRef(v->GetType()).has_value();
593	        })) {
594	      return MakeMemRefLessAssign(op, new_value);
595	    }
596	
597	    // Check if the RHS is a Call expression
598	    if (auto call = std::dynamic_pointer_cast<const Call>(op->value_)) {
599	      LOG_DEBUG << "Processing AssignStmt for " << op->var_->name_hint_ << " with call to "
600	                << call->op_->name_;
601	
602	      // A view / in-place result physically IS its source's buffer, so binding
603	      // it to a different one cannot be honored. Say so instead of silently
604	      // dropping the binding — the user asked for something impossible.
605	      CHECK_SPAN(!op_predicates::OutputInheritsSourceBuffer(call->op_->name_) ||
606	                     !HasUserBinding(op->var_->GetType()),
607	                 op->var_->span_)
608	          << "Tile '" << op->var_->name_hint_ << "' is produced by '" << call->op_->name_
609	          << "', which lands in its source tile's allocation, so it cannot be given one of its own. "
610	             "Bind the source tile instead.";
611	
612	      // Handle view operations: output should share MemRef with input tile.
613	      // A pure metadata view (slice/reshape/...) inherits its input's buffer.  A
614	      // permuting inherit-input op — tile.transpose — must NOT: pto.ttrans is
615	      // not in-place safe (the unaligned scalar path writes dst directly from
616	      // src), so the transpose output always gets a fresh buffer.
617	      if (IsViewOperation(call->op_->name_) && call->args_.size() > 0) {
618	        LOG_DEBUG << "Detected view operation: " << call->op_->name_;
619	        // Get the input tile (first argument) after mutation
620	        auto new_call = std::dynamic_pointer_cast<const Call>(new_value);
621	        if (new_call && !new_call->args_.empty()) {
622	          const bool may_inherit = !IsDataPermutingInheritOp(call->op_);
623	          if (may_inherit) {
624	            auto result = ShareMemRefFrom(new_call->args_[0], op, new_value);
625	            if (result) {
626	              LOG_DEBUG << "Sharing MemRef from input tile to " << op->var_->name_hint_;
627	              return result;
628	            }
629	            LOG_DEBUG << "Input tile has no MemRef yet";
630	          }
631	        }
632	      }
633	
634	      // Handle ops whose output reuses a specific input arg's MemRef (registry-based)
635	      auto reuse_arg_idx = GetOutputReusesInputArg(call->op_->name_);
636	      if (reuse_arg_idx.has_value()) {
637	        auto new_call = std::dynamic_pointer_cast<const Call>(new_value);
638	        if (new_call && *reuse_arg_idx < new_call->args_.size()) {
639	          auto result = ShareMemRefFrom(new_call->args_[*reuse_arg_idx], op, new_value);
640	          if (result) {
641	            LOG_DEBUG << "Reusing MemRef from input arg " << *reuse_arg_idx << " for "
642	                      << op->var_->name_hint_;
643	            return result;
644	          }
645	        }
646	      }
647	    }
648	
649	    // Tile alias: a = b where b is a tile Var — share b's MemRef.
650	    // Without this, the alias gets a fresh MemRef that is never written to,
651	    // breaking IfStmt return_vars that inherit the alias's empty MemRef.
652	    if (auto value_var = As<Var>(new_value)) {
653	      if (As<TileType>(op->var_->GetType())) {
654	        auto result = ShareMemRefFrom(value_var, op, new_value);
655	        if (result) return result;
656	      }
657	    }
658	
659	    // Default case: visit the variable normally
660	    auto new_var = GetNewVar(op->var_);
661	    return std::make_shared<AssignStmt>(new_var, new_value, op->span_);
662	  }
663	
664	  StmtPtr VisitStmt_(const ForStmtPtr& op) override {
665	    // Manual traversal of ForStmt fields to ensure correct MemRef assignment:
666	    // - iter_args inherit MemRef from initValue (via ProcessIterArg)
667	    // - return_vars share MemRef with corresponding yield values
668	
669	    // Step 1: Visit loop bounds and loop_var
670	    auto new_loop_var_expr = VisitExpr(op->loop_var_);
671	    auto new_loop_var = As<Var>(new_loop_var_expr);
672	    INTERNAL_CHECK_SPAN(new_loop_var, op->span_)
673	        << "Internal error: ForStmt loop_var is not a Var after mutation";
674	    auto new_start = VisitExpr(op->start_);
675	    auto new_stop = VisitExpr(op->stop_);
676	    auto new_step = VisitExpr(op->step_);
677	
678	    // Step 2: Process iter_args (inherits MemRef from initValue via ProcessIterArg)
679	    std::vector<IterArgPtr> new_iter_args;
680	    new_iter_args.reserve(op->iter_args_.size());
681	    for (const auto& ia : op->iter_args_) {
682	      auto new_ia_expr = VisitExpr(ia);
683	      auto new_ia =
684	          std::dynamic_pointer_cast<const IterArg>(std::static_pointer_cast<const IRNode>(new_ia_expr));
685	      INTERNAL_CHECK_SPAN(new_ia, op->span_)
686	          << "Internal error: ForStmt iter_arg is not an IterArg after mutation";
687	      new_iter_args.push_back(new_ia);
688	    }
689	
690	    // Register old->new IterArg mappings so body references are substituted
691	    for (size_t i = 0; i < op->iter_args_.size(); ++i) {
692	      if (new_iter_args[i].get() != op->iter_args_[i].get()) {
693	        var_remap_[op->iter_args_[i].get()] = new_iter_args[i];
694	      }
695	    }
696	
697	    // Step 3: Visit body
698	    auto new_body = VisitStmt(op->body_);
699	
700	    // Clean up IterArg remappings
701	    for (const auto& old_iter_arg : op->iter_args_) {
702	      var_remap_.erase(old_iter_arg.get());
703	    }
704	
705	    // Step 4: Visit return_vars
706	    std::vector<VarPtr> new_return_vars;
707	    new_return_vars.reserve(op->return_vars_.size());
708	    for (const auto& rv : op->return_vars_) {
709	      auto new_rv_expr = VisitExpr(rv);
710	      auto new_rv = As<Var>(new_rv_expr);
711	      INTERNAL_CHECK_SPAN(new_rv, op->span_)
712	          << "Internal error: ForStmt return_var is not a Var after mutation";
713	      new_return_vars.push_back(new_rv);
714	    }
715	
716	    auto new_for = MutableCopy(op);
717	    new_for->loop_var_ = new_loop_var;
718	    new_for->start_ = new_start;
719	    new_for->stop_ = new_stop;
720	    new_for->step_ = new_step;
721	    new_for->iter_args_ = new_iter_args;
722	    new_for->body_ = new_body;
723	    new_for->return_vars_ = new_return_vars;
724	
725	    // Patch return_vars so each shares its iter_arg's MemRef (inherited from initValue).
726	    // This establishes the invariant that initValue/iter_arg/return_var all share the
727	    // same MemRef buffer — the loop accumulator lives in one place for the whole loop.
728	    // Any yield-vs-buffer mismatch is the concern of downstream passes.
729	    if (new_for->iter_args_.empty() || new_for->return_vars_.empty()) {
730	      return new_for;
731	    }
732	
733	    auto get_iter_arg_var = [&](size_t i) -> VarPtr {
734	      if (i >= new_for->iter_args_.size()) return nullptr;
735	      return std::static_pointer_cast<const Var>(new_for->iter_args_[i]);
736	    };
737	    auto [patched, changed] =
738	        PatchReturnVarsFromYield(new_for->return_vars_, op->return_vars_, get_iter_arg_var);
739	
740	    if (!changed) return new_for;
741	
742	    new_for->return_vars_ = std::move(patched);
743	    return new_for;
744	  }
745	
746	  StmtPtr VisitStmt_(const IfStmtPtr& op) override {
747	    auto result = IRMutator::VisitStmt_(op);
748	    auto new_if = As<IfStmt>(result);
749	    if (!new_if || new_if->return_vars_.empty()) return result;
750	
751	    auto then_yield = FindYieldStmt(new_if->then_body_);
752	    auto else_yield = new_if->else_body_.has_value() ? FindYieldStmt(new_if->else_body_.value()) : nullptr;
753	    if (!then_yield && !else_yield) return result;
754	
755	    auto get_yield_var = [&](size_t i) -> VarPtr {
756	      VarPtr var = nullptr;
757	      if (then_yield && i < then_yield->value_.size()) var = As<Var>(then_yield->value_[i]);
758	      if (!var && else_yield && i < else_yield->value_.size()) var = As<Var>(else_yield->value_[i]);
759	      return var;
760	    };
761	    auto [patched, changed] = PatchReturnVarsFromYield(new_if->return_vars_, op->return_vars_, get_yield_var);
762	
763	    if (!changed) return result;
764	
765	    auto patched_if = MutableCopy(new_if);
766	    patched_if->return_vars_ = std::move(patched);
767	    return patched_if;
768	  }
769	
770	 private:
771	  // Shared logic for ForStmt/IfStmt: patch each return_var to share its yield value's MemRef.
772	  // get_yield_var(i) resolves the yield variable for the i-th return_var.
773	  using YieldVarResolver = std::function<VarPtr(size_t)>;
774	  std::pair<std::vector<VarPtr>, bool> PatchReturnVarsFromYield(const std::vector<VarPtr>& new_return_vars,
775	                                                                const std::vector<VarPtr>& old_return_vars,
776	                                                                const YieldVarResolver& get_yield_var) {
777	    bool changed = false;
778	    std::vector<VarPtr> patched;
779	    patched.reserve(new_return_vars.size());
780	
781	    for (size_t i = 0; i < new_return_vars.size(); ++i) {
782	      auto yield_var = get_yield_var(i);
783	      auto yield_tile = yield_var ? GetTileTypeWithMemRef(yield_var->GetType()) : nullptr;
784	      if (As<TileType>(new_return_vars[i]->GetType()) && yield_tile) {
785	        auto new_type = CloneTypeWithMemRef(new_return_vars[i]->GetType(), yield_tile->memref_,
786	                                            yield_tile->GetMemorySpace());
787	        auto new_rv =
788	            std::make_shared<Var>(new_return_vars[i]->name_hint_, new_type, new_return_vars[i]->span_);
789	        var_map_[old_return_vars[i]] = new_rv;
790	        patched.push_back(new_rv);
791	        changed = true;
792	      } else {
793	        patched.push_back(new_return_vars[i]);
794	      }
795	    }
796	    return {std::move(patched), changed};
797	  }
798	
799	  std::map<VarPtr, VarPtr> var_map_;
800	  const DeclaredAllocMap& declared_allocs_;
801	  const backend::BackendHandler* handler_ = nullptr;
802	  FunctionType func_type_ = FunctionType::InCore;
803	  uint64_t next_id_ = 0;
804	};
