806	// Insert alloc statements at the beginning of a function body.
807	/**
808	 * @brief Initialize MemRef for all variables in a function
809	 *
810	 * This transformation:
811	 * 1. Normalizes statement structure (ensures SeqStmts)
812	 * 2. Initializes the MemRef field for all Var nodes
813	 * 3. Creates tile.alloc operations for non-DDR MemRefs (addr=-1, unallocated)
814	 *
815	 * Memory space is read from TileType::memory_space_ (set by InferTileMemorySpace).
816	 * Variables without memory_space default to DDR.
817	 */
818	FunctionPtr TransformInitMemRef(const FunctionPtr& func) {
819	  // Step 1: Normalize statement structure to ensure SeqStmts
820	  auto normalized_func = NormalizeStmtStructure(func);
821	
822	  const auto* ctx = PassContext::Current();
823	  const backend::BackendHandler* handler = nullptr;
824	  if (backend::BackendConfig::IsConfigured()) {
825	    handler = ctx ? ctx->GetBackendHandler() : backend::GetBackend()->GetHandler();
826	  }
827	
828	  // Step 2: Resolve author-declared allocations (`pl.Tile[..., pl.MemRef("name"),
829	  // ...]`), then mutate variables to initialize their MemRef. They must be
830	  // collected up front: a declared allocation's size is the max over ALL tiles
831	  // bound to it, which is only known after the whole function has been seen.
832	  DeclaredAllocCollector declared_alloc_collector(handler);
833	  declared_alloc_collector.VisitStmt(normalized_func->body_);
834	  const DeclaredAllocMap& declared_allocs = declared_alloc_collector.buffers;
835	
836	  // The isolation guarantee is enforced by MemoryReuse under PYPTO and by the
837	  // allocation constraints under DSA-RP. PTOAS replaces PyPTO memory planning
838	  // wholesale; honoring the declaration's allocation but not its isolation
839	  // would hand back exactly the coalescing the author declared it to prevent,
840	  // so reject the unsupported combination rather than degrade quietly.
841	  //
842	  // A MULTI-SLOT declaration is the exception: it lowers to a ptoas
843	  // `pto.alloc_multi_tile` region, and ptoas plans the N slots into disjoint
844	  // physical segments it is explicitly forbidden to alias-merge. The separation
845	  // the author asked for — slot k is not slot j — is therefore carried into ptoas
846	  // rather than lost, which is the whole reason the multi-buffer form exists. A
847	  // single-slot declaration has no such counterpart and stays rejected.
848	  if (ctx != nullptr && ctx->GetMemoryPlanner() == MemoryPlanner::PtoAS) {
849	    for (const auto& [base, alloc] : declared_allocs) {
850	      CHECK(alloc.slot_count > 1)
851	          << "A single-slot declared allocation (pl.MemRef(\"" << base->name_hint_
852	          << "\")) is not supported under memory_planner=PTOAS: ptoas owns memory planning and "
853	             "would be free to coalesce the allocations you separated. Declare it with "
854	             "pl.MemRef(slots=N) — N slots become one ptoas multi-buffer region whose slots ptoas "
855	             "keeps disjoint — or compile with the default PyPTO memory planner.";
856	    }
857	  }
858	
859	  InitMemRefMutator mutator(declared_allocs, handler, normalized_func->func_type_);
860	
861	  std::vector<VarPtr> new_params;
862	  new_params.reserve(normalized_func->params_.size());
863	  for (const auto& var : normalized_func->params_) {
864	    auto new_param = mutator.GetNewVar(var);
865	    INTERNAL_CHECK_SPAN(new_param, var->span_) << "Failed to get new param";
866	    new_params.push_back(new_param);
867	  }
868	
869	  auto new_body = mutator.VisitStmt(normalized_func->body_);
870	
871	  auto result_func = MutableCopy(normalized_func);
872	  result_func->params_ = new_params;
873	  result_func->body_ = new_body;
874	
875	  // Step 3: Collect ALL MemRefs (DDR gets tensor.alloc, on-chip gets tile.alloc)
876	  memref_collectors::MemRefWithSpaceCollector collector(/*skip_ddr=*/false);
877	  for (const auto& param : new_params) {
878	    collector.VisitExpr(param);
879	  }
880	  collector.VisitStmt(new_body);
881	
882	  const auto& memrefs = collector.memrefs;
883	  if (memrefs.empty()) return result_func;
884	
885	  // Deduplicate by base_ Ptr — one alloc per unique base
886	  std::set<const Var*> seen_bases;
887	  std::vector<StmtPtr> alloc_stmts;
888	  alloc_stmts.reserve(memrefs.size());
889	  for (const auto& [memref, memory_space] : memrefs) {
890	    if (seen_bases.insert(memref->base_.get()).second) {
891	      // A declared allocation covers all its slots; the MemRef that happens to be
892	      // seen first names only one of them, so take the size from the collector.
893	      auto declared = declared_allocs.find(memref->base_.get());
894	      const bool pinned = declared != declared_allocs.end();
895	      auto alloc_size = pinned ? std::make_optional(declared->second.TotalSize()) : std::optional<uint64_t>{};
896	      alloc_stmts.push_back(CreateAllocStatement(memref, memory_space, pinned, alloc_size));
897	    }
898	  }
899	
900	  // Step 4: Insert alloc statements at the beginning of the function body
901	  auto final_body = InsertAllocsIntoBody(new_body, alloc_stmts);
902	
903	  result_func->body_ = final_body;
904	  return result_func;
905	}
