927	  void VisitStmt_(const AssignStmtPtr& op) override {
928	    if (!op || !op->var_ || !op->var_->GetType()) return;
929	    auto tile_type = std::dynamic_pointer_cast<const TileType>(op->var_->GetType());
930	    if (tile_type && !tile_type->memref_.has_value()) {
931	      if (IsBufferLessByDesign(op)) {
932	        buffer_less_.insert(op->var_.get());
933	      } else {
934	        diagnostics_.emplace_back(
935	            DiagnosticSeverity::Error, "HasMemRefs", 0,
936	            "TileType variable '" + op->var_->name_hint_ + "' has no MemRef initialized", op->var_->span_);
937	      }
938	    }
939	    IRVisitor::VisitStmt_(op);
940	  }
941	
942	 private:
943	  // A cross-core tpop result (its data lives in the reserved C2V/V2C slot, not a
944	  // tile MemRef) and any zero-copy view / plain alias chained off such a result
945	  // legitimately carry no MemRef. Shares the rule with the MemRef-creating mutator
946	  // via ProducesBufferLessTile; here a source is buffer-less iff it is tracked.
947	  [[nodiscard]] bool IsBufferLessByDesign(const AssignStmtPtr& op) const {
948	    return ProducesBufferLessTile(op->value_, [this](const Var* v) { return buffer_less_.count(v) > 0; });
949	  }
950	
951	  std::set<const Var*> buffer_less_;
952	  std::vector<Diagnostic>& diagnostics_;
953	};
954	
955	}  // namespace
956	
957	class HasMemRefsPropertyVerifierImpl : public PropertyVerifier {
958	 public:
959	  [[nodiscard]] std::string GetName() const override { return "HasMemRefs"; }
960	
961	  void Verify(const ProgramPtr& program, std::vector<Diagnostic>& diagnostics) override {
962	    if (!program) return;
963	    for (const auto& [gv, func] : program->functions_) {
964	      if (!func || !func->body_) continue;
965	      HasMemRefsVerifier verifier(diagnostics);
966	      verifier.VisitStmt(func->body_);
967	    }
968	  }
969	};
970	
971	PropertyVerifierPtr CreateHasMemRefsPropertyVerifier() {
972	  return std::make_shared<HasMemRefsPropertyVerifierImpl>();
973	}
974	
975	}  // namespace ir
976	}  // namespace pypto
