54	inline TypePtr CloneTypeWithMemRef(const TypePtr& type, const std::optional<MemRefPtr>& memref,
55	                                   std::optional<MemorySpace> tile_memory_space_override = std::nullopt) {
56	  // DistributedTensorType inherits TensorType: dispatch on it first so the
57	  // returned clone preserves the subclass identity (including the
58	  // window_buffer_ back-reference). Without this guard the more generic
59	  // ``TensorType`` branch below would silently downgrade DistributedTensor
60	  // params during memref/SSA rebuilds — by codegen time the var's type would
61	  // become plain TensorType and the cross-rank op codegen would lose the
62	  // ``DistributedTensorType`` kind discriminator (see N6 plan §codegen).
63	  if (auto dist_type = std::dynamic_pointer_cast<const DistributedTensorType>(type)) {
64	    return std::make_shared<DistributedTensorType>(dist_type->shape_, dist_type->dtype_, memref,
65	                                                   dist_type->tensor_view_, dist_type->window_buffer_);
66	  }
67	
68	  if (auto tensor_type = std::dynamic_pointer_cast<const TensorType>(type)) {
69	    return std::make_shared<TensorType>(tensor_type->shape_, tensor_type->dtype_, memref,
70	                                        tensor_type->tensor_view_);
71	  }
72	
73	  if (auto tile_type = std::dynamic_pointer_cast<const TileType>(type)) {
74	    auto memory_space =
75	        tile_memory_space_override.has_value() ? tile_memory_space_override : tile_type->memory_space_;
76	    return std::make_shared<TileType>(tile_type->shape_, tile_type->dtype_, memref, tile_type->tile_view_,
77	                                      memory_space);
78	  }
79	
80	  return type;
81	}
82	
83	template <typename RemapExprFn>
84	inline std::vector<ExprPtr> RemapTypeExprVector(const std::vector<ExprPtr>& exprs,
85	                                                const RemapExprFn& remap_expr, bool& changed) {
86	  std::vector<ExprPtr> new_exprs;
87	  new_exprs.reserve(exprs.size());
88	  for (const auto& expr : exprs) {
89	    auto new_expr = remap_expr(expr);
90	    if (new_expr.get() != expr.get()) {
91	      changed = true;
92	    }
93	    new_exprs.push_back(std::move(new_expr));
94	  }
95	  return new_exprs;
96	}
97	
98	template <typename RemapExprFn>
99	inline std::optional<TensorView> RemapTensorViewExprs(const std::optional<TensorView>& tensor_view,
100	                                                      const RemapExprFn& remap_expr, bool& changed) {
101	  if (!tensor_view.has_value()) {
102	    return tensor_view;
103	  }
104	  bool view_changed = false;
105	  auto new_stride = RemapTypeExprVector(tensor_view->stride, remap_expr, view_changed);
106	  auto new_valid_shape = RemapTypeExprVector(tensor_view->valid_shape, remap_expr, view_changed);
107	  if (!view_changed) {
108	    return tensor_view;
109	  }
110	  changed = true;
111	  return TensorView(std::move(new_stride), tensor_view->layout, std::move(new_valid_shape), tensor_view->pad);
112	}
113	
114	template <typename RemapExprFn>
115	inline std::optional<TileView> RemapTileViewExprs(const std::optional<TileView>& tile_view,
116	                                                  const RemapExprFn& remap_expr, bool& changed) {
117	  if (!tile_view.has_value()) {
118	    return tile_view;
119	  }
120	  bool view_changed = false;
121	  auto new_valid_shape = RemapTypeExprVector(tile_view->valid_shape, remap_expr, view_changed);
122	  auto new_stride = RemapTypeExprVector(tile_view->stride, remap_expr, view_changed);
123	  ExprPtr new_start_offset = tile_view->start_offset;
124	  if (tile_view->start_offset) {
125	    new_start_offset = remap_expr(tile_view->start_offset);
126	    if (new_start_offset.get() != tile_view->start_offset.get()) {
127	      view_changed = true;
128	    }
129	  }
130	  if (!view_changed) {
131	    return tile_view;
132	  }
133	  changed = true;
134	  return TileView(std::move(new_valid_shape), std::move(new_stride), std::move(new_start_offset),
135	                  tile_view->blayout, tile_view->slayout, tile_view->fractal, tile_view->pad,
136	                  tile_view->compact);
137	}
138	
139	/// Rewrite the SSA values a *pinned* MemRef's slot index names.
140	///
141	/// A declared allocation's slot index may be a runtime expression (`l0c[i & 1]`),
142	/// which makes it the only MemRef field that substitution has to follow: rename
143	/// `i` and the index must follow, or it dangles on a stale Var.
144	///
145	/// Restricted to pinned MemRefs on purpose. `byte_offset_` needs no remap — it is
146	/// `ConstInt(0)` until InitMemRef and a concrete address after — and confining
147	/// rebuilds to the pinned window keeps them strictly before every pass that keys
148	/// on MemRef *pointer* identity (`AllocateMemoryAddr` matches old→new by raw
149	/// pointer). Rebuilding one of those later would silently split a shared MemRef.
150	template <typename RemapExprFn>
151	inline std::optional<MemRefPtr> RemapPinnedMemRefExprs(const std::optional<MemRefPtr>& memref,
152	                                                       const RemapExprFn& remap_expr, bool& changed) {
153	  if (!memref.has_value() || !(*memref)->is_pinned_) return memref;
154	  const auto& slot_index = (*memref)->slot_index_;
155	  if (!slot_index.has_value() || !*slot_index) return memref;
156	  auto new_index = remap_expr(*slot_index);
157	  if (new_index == *slot_index) return memref;
158	  changed = true;
159	  const auto& old = *memref;
160	  return std::make_optional<MemRefPtr>(
161	      std::make_shared<MemRef>(old->name_hint_, old->base_, old->byte_offset_, old->size_, old->span_,
162	                               old->is_pinned_, old->slot_count_, std::make_optional(std::move(new_index))));
163	}
164	
165	template <typename RemapExprFn>
166	inline TypePtr CloneTypeWithMemRefAndRemapExprs(
167	    const TypePtr& type, const std::optional<MemRefPtr>& memref_in, const RemapExprFn& remap_expr,
168	    std::optional<MemorySpace> tile_memory_space_override = std::nullopt) {
169	  const bool memref_changed = GetTypeMemRef(type) != memref_in;
170	  bool changed = memref_changed;
171	  const auto memref = RemapPinnedMemRefExprs(memref_in, remap_expr, changed);
172	
173	  // DistributedTensorType clone path: matches the comment on
174	  // CloneTypeWithMemRef above. Distinct from the TensorType branch so the
175	  // window_buffer_ back-reference and the kind discriminator survive an
176	  // InitMemRef / SSA rebuild.
177	  if (auto dist_type = std::dynamic_pointer_cast<const DistributedTensorType>(type)) {
178	    auto new_shape = RemapTypeExprVector(dist_type->shape_, remap_expr, changed);
179	    auto new_tensor_view = RemapTensorViewExprs(dist_type->tensor_view_, remap_expr, changed);
180	    if (!changed) {
181	      return type;
182	    }
183	    return std::make_shared<DistributedTensorType>(std::move(new_shape), dist_type->dtype_, memref,
184	                                                   std::move(new_tensor_view), dist_type->window_buffer_);
185	  }
186	
187	  if (auto tensor_type = std::dynamic_pointer_cast<const TensorType>(type)) {
188	    auto new_shape = RemapTypeExprVector(tensor_type->shape_, remap_expr, changed);
189	    auto new_tensor_view = RemapTensorViewExprs(tensor_type->tensor_view_, remap_expr, changed);
190	    if (!changed) {
191	      return type;
192	    }
193	    return std::make_shared<TensorType>(std::move(new_shape), tensor_type->dtype_, memref,
194	                                        std::move(new_tensor_view));
195	  }
196	
197	  if (auto tile_type = std::dynamic_pointer_cast<const TileType>(type)) {
198	    auto memory_space =
199	        tile_memory_space_override.has_value() ? tile_memory_space_override : tile_type->memory_space_;
200	    auto new_shape = RemapTypeExprVector(tile_type->shape_, remap_expr, changed);
201	    auto new_tile_view = RemapTileViewExprs(tile_type->tile_view_, remap_expr, changed);
202	    if (!changed) {
203	      return type;
204	    }
205	    return std::make_shared<TileType>(std::move(new_shape), tile_type->dtype_, memref,
206	                                      std::move(new_tile_view), memory_space);
207	  }
208	
209	  return type;
210	}
211	
212	inline std::shared_ptr<const TileType> GetTileTypeWithMemRef(const TypePtr& type) {
213	  auto tile_type = std::dynamic_pointer_cast<const TileType>(type);
214	  if (!tile_type || !tile_type->memref_.has_value()) {
215	    return nullptr;
216	  }
217	  return tile_type;
218	}
219	
220	inline MemRefPtr GetDefinedMemRef(const std::shared_ptr<const TileType>& tile_type) {
221	  CHECK(tile_type != nullptr) << "TileType must not be null";
222	  CHECK(tile_type->memref_.has_value()) << "TileType must carry MemRef";
223	  return *tile_type->memref_;
224	}
225	
226	/// How two MemRefs' start addresses relate.
227	enum class AddressRelation {
228	  kSame,       ///< provably the same address
229	  kDifferent,  ///< provably different addresses
230	  kUnknown,    ///< same allocation, offsets neither provably equal nor provably apart
231	};
232	
233	/// Compare where two MemRefs start, more precisely than `MemRef::SameAllocation`.
234	///
235	/// `SameAllocation` compares only the base Ptr, so two slots of one
236	/// `pl.MemRef(slots=N)` look like the same storage. Use this wherever the
237	/// question is whether a value already sits where it has to end up: between two
238	/// slots of one allocation a reconciling copy is still required.
239	///
240	/// Size is deliberately not compared. A padded loop-carried accumulator carries
241	/// its buffer under one valid shape and yields it under another, so the two
242	/// MemRefs describe the same storage at differing extents; requiring equal sizes
243	/// would ask for a copy from a buffer onto itself, which for `Acc` has no legal
244	/// lowering at all.
245	///
246	/// Offsets compare through `AreExprsEqual`, so a runtime slot subscript written
247	/// twice (`buf[i % 2]` at two sites builds two structurally identical trees)
248	/// still reports `kSame`. What it cannot prove either way is `kUnknown` — two
249	/// *different* symbolic offsets into one allocation may or may not land on the
250	/// same bytes. Callers that would move data must reject that case rather than
251	/// guess: copying is unsafe when the addresses turn out equal, and skipping is
252	/// unsafe when they do not.
253	inline AddressRelation CompareBaseAddress(const MemRefPtr& a, const MemRefPtr& b) {
254	  CHECK(a != nullptr && b != nullptr) << "MemRef must not be null";
255	  if (a->base_.get() != b->base_.get()) return AddressRelation::kDifferent;
256	  if (AreExprsEqual(a->byte_offset_, b->byte_offset_)) return AddressRelation::kSame;
257	  // AreExprsEqual folds ConstInt by value, so two constants that compare unequal
258	  // really are different addresses; anything else is symbolic and unprovable.
259	  if (As<ConstInt>(a->byte_offset_) && As<ConstInt>(b->byte_offset_)) return AddressRelation::kDifferent;
260	  return AddressRelation::kUnknown;
261	}
262	
263	inline bool TryRegisterUniqueMemRef(const MemRefPtr& memref, MemorySpace memory_space,
264	                                    std::map<const MemRef*, MemorySpace>& seen_ptrs) {
265	  CHECK(memref != nullptr) << "MemRef must not be null";
266	  auto [it, inserted] = seen_ptrs.emplace(memref.get(), memory_space);
267	  CHECK(inserted || it->second == memory_space)
268	      << "Conflicting TileType.memory_space values found for the same MemRef";
269	  return inserted;
270	}
271	
272	// ============================================================================
273	// Base Ptr name construction and parsing
274	// ============================================================================
275	
276	/// Build a base Ptr variable name from memory space and counter: "mem_vec_7"
277	inline std::string BuildBasePtrName(MemorySpace space, uint64_t id) {
278	  std::string space_str = MemorySpaceToString(space);
279	  std::transform(space_str.begin(), space_str.end(), space_str.begin(),
280	                 [](unsigned char c) { return std::tolower(c); });
281	  return "mem_" + space_str + "_" + std::to_string(id);
282	}
283	
284	/// Build a base Ptr variable name from counter only: "mem_7"
285	inline std::string BuildBasePtrName(uint64_t id) { return "mem_" + std::to_string(id); }
286	
287	/// Extract the trailing numeric counter from a base Ptr name (e.g., "mem_vec_7" → 7).
288	/// Returns std::nullopt if the name has no trailing numeric suffix.
289	inline std::optional<uint64_t> ExtractNameCounter(const std::string& name) {
290	  auto pos = name.find_last_of('_');
291	  if (pos == std::string::npos || pos + 1 >= name.size()) return std::nullopt;
292	  const std::string suffix = name.substr(pos + 1);
293	  if (suffix.empty() ||
294	      !std::all_of(suffix.begin(), suffix.end(), [](unsigned char c) { return std::isdigit(c); })) {
295	    return std::nullopt;
296	  }
297	  return std::stoull(suffix);
298	}
299	
300	// ============================================================================
301	// Alloc statement creation
302	// ============================================================================
303	
304	/// Create an alloc AssignStmt for a MemRef's base Ptr variable.
305	/// DDR → tensor.alloc, on-chip → tile.alloc.
306	/// Emits: base_ptr: Ptr = {tile,tensor}.alloc(memory_space, size)
307	/// `alloc_size` overrides the reserved bytes when the allocation is larger than
308	/// the MemRef that names it. That happens for a multi-slot declared allocation:
309	/// each slot MemRef is sized to its own slot (so its byte range stays inside the
310	/// slot), while the allocation has to cover every slot.
311	inline StmtPtr CreateAllocStatement(const MemRefPtr& memref, MemorySpace memory_space, bool pinned = false,
312	                                    std::optional<uint64_t> alloc_size = std::nullopt) {
313	  std::string op_name = (memory_space == MemorySpace::DDR) ? "tensor.alloc" : "tile.alloc";
314	  auto alloc_op = std::make_shared<Op>(op_name);
315	
316	  auto memspace_expr =
317	      std::make_shared<ConstInt>(static_cast<int64_t>(memory_space), DataType::INDEX, Span::unknown());
318	  auto size_expr = std::make_shared<ConstInt>(static_cast<int64_t>(alloc_size.value_or(memref->size_)),
319	                                              DataType::INDEX, Span::unknown());
320	
321	  std::vector<ExprPtr> alloc_args = {memspace_expr, size_expr};
322	  // Only emit the kwarg when set, so ordinary compiler allocations print and
323	  // compare exactly as before.
324	  std::vector<std::pair<std::string, std::any>> alloc_kwargs;
325	  if (pinned) alloc_kwargs.emplace_back("pinned", true);
326	  auto alloc_call =
327	      std::make_shared<Call>(alloc_op, alloc_args, std::move(alloc_kwargs), GetPtrType(), Span::unknown());
328	
329	  return std::make_shared<AssignStmt>(memref->base_, alloc_call, Span::unknown());
330	}
331	
332	/// Prepend alloc statements to a function body's top-level statement list.
333	///
334	/// Every consumer of the allocation list scans the body's top-level `SeqStmts`
335	/// (see `CollectPinnedAllocSizes`), so an allocation created after `InitMemRef`
336	/// has to land there too rather than beside its first use.
337	inline StmtPtr InsertAllocsIntoBody(const StmtPtr& body, const std::vector<StmtPtr>& alloc_stmts) {
338	  if (alloc_stmts.empty()) return body;
339	
340	  std::vector<StmtPtr> new_seq_stmts;
341	  new_seq_stmts.insert(new_seq_stmts.end(), alloc_stmts.begin(), alloc_stmts.end());
342	
343	  const Span& span = body ? body->span_ : alloc_stmts.front()->span_;
344	  if (body) {
345	    if (auto seq = As<SeqStmts>(body)) {
346	      new_seq_stmts.insert(new_seq_stmts.end(), seq->stmts_.begin(), seq->stmts_.end());
347	    } else {
348	      new_seq_stmts.push_back(body);
349	    }
350	  }
351	
352	  return SeqStmts::Flatten(std::move(new_seq_stmts), span);
353	}
354	
355	/// The base Ptr an alloc statement declares when it is a user-owned (pinned)
356	/// buffer, else null. Null for every compiler-created allocation.
357	inline VarPtr GetPinnedAllocBase(const StmtPtr& stmt) {
358	  auto assign = As<AssignStmt>(stmt);
359	  if (!assign) return nullptr;
360	  auto call = As<Call>(assign->value_);
361	  if (!call || !call->op_) return nullptr;
362	  if (!IsOp(call, "tile.alloc") && !IsOp(call, "tensor.alloc")) return nullptr;
363	  return call->GetKwarg<bool>("pinned", false) ? assign->var_ : nullptr;
364	}
365	
366	// ============================================================================
367	// Byte offset computation helpers
368	// ============================================================================
369	
370	/// Create a ConstInt(0) expression for byte offset initialization.
371	inline ExprPtr MakeZeroByteOffset() {
372	  return std::make_shared<ConstInt>(0, DataType::INDEX, Span::unknown());
373	}
374	
375	/// Create an addition expression: lhs + rhs.
376	/// Folds ConstInt + ConstInt into a single ConstInt.
377	inline ExprPtr AddByteOffsets(const ExprPtr& lhs, const ExprPtr& rhs) {
378	  auto const_lhs = As<ConstInt>(lhs);
379	  auto const_rhs = As<ConstInt>(rhs);
380	  if (const_lhs && const_rhs) {
381	    return std::make_shared<ConstInt>(const_lhs->value_ + const_rhs->value_, DataType::INDEX,
382	                                      Span::unknown());
383	  }
384	  if (const_rhs && const_rhs->value_ == 0) return lhs;
385	  if (const_lhs && const_lhs->value_ == 0) return rhs;
386	  return std::make_shared<Add>(lhs, rhs, DataType::INDEX, Span::unknown());
387	}
388	
389	/// Create a multiply expression: lhs * rhs.
390	/// Folds ConstInt * ConstInt into a single ConstInt.
391	inline ExprPtr MulByteOffsets(const ExprPtr& lhs, const ExprPtr& rhs) {
392	  auto const_lhs = As<ConstInt>(lhs);
393	  auto const_rhs = As<ConstInt>(rhs);
394	  if (const_lhs && const_rhs) {
395	    return std::make_shared<ConstInt>(const_lhs->value_ * const_rhs->value_, DataType::INDEX,
396	                                      Span::unknown());
397	  }
398	  if (const_rhs && const_rhs->value_ == 1) return lhs;
399	  if (const_lhs && const_lhs->value_ == 1) return rhs;
400	  return std::make_shared<Mul>(lhs, rhs, DataType::INDEX, Span::unknown());
401	}
402	
403	/// Compute byte offset for a slice operation.
404	/// byte_offset = (o0 * s1 * ... * sN + o1 * s2 * ... * sN + ... + oN) * storage_bits / 8
405	///
406	/// MemRef carries a byte offset rather than a nibble offset. Packed 4-bit
407	/// slices therefore require a static, byte-aligned logical origin in v1.
408	inline ExprPtr ComputeSliceByteOffset(const std::vector<ExprPtr>& offsets,
409	                                      const std::vector<ExprPtr>& parent_shape, const DataType& dtype,
410	                                      const Span& span) {
411	  INTERNAL_CHECK(offsets.size() == parent_shape.size())
412	      << "Internal error: slice offset rank (" << offsets.size() << ") must match parent shape rank ("
413	      << parent_shape.size() << ")";
414	
415	  ExprPtr result = MakeZeroByteOffset();
416	
417	  for (size_t i = 0; i < offsets.size(); ++i) {
418	    ExprPtr stride = std::make_shared<ConstInt>(1, DataType::INDEX, Span::unknown());
419	    for (size_t j = i + 1; j < parent_shape.size(); ++j) {
420	      stride = MulByteOffsets(stride, parent_shape[j]);
421	    }
422	    result = AddByteOffsets(result, MulByteOffsets(offsets[i], stride));
423	  }
424	
425	  const uint64_t storage_bits = storage_size::GetStorageBitWidth(dtype);
426	  INTERNAL_CHECK_SPAN(storage_bits > 0, span)
427	      << "Internal error: slice dtype has no storage width: " << dtype.ToString();
428	  if (storage_bits % 8 == 0) {
429	    auto elem_size_expr =
430	        std::make_shared<ConstInt>(static_cast<int64_t>(storage_bits / 8), DataType::INDEX, Span::unknown());
431	    return MulByteOffsets(result, elem_size_expr);
432	  }
433	
434	  auto logical_offset = As<ConstInt>(result);
435	  CHECK_SPAN(logical_offset, span)
436	      << "Packed 4-bit slice offsets must be compile-time constants because MemRef cannot represent "
437	         "a dynamic nibble offset";
438	  CHECK_SPAN(logical_offset->value_ >= 0, span)
439	      << "Packed 4-bit slice offsets must be non-negative, but got logical offset " << logical_offset->value_;
440	  const auto byte_offset =
441	      storage_size::StaticLogicalOffsetToByte(static_cast<uint64_t>(logical_offset->value_), dtype);
442	  CHECK_SPAN(byte_offset.has_value(), span)
443	      << "Packed 4-bit slice origins must be byte-aligned; logical linear offset " << logical_offset->value_
444	      << " selects the second nibble of a byte";
445	  CHECK_SPAN(*byte_offset <= static_cast<uint64_t>(std::numeric_limits<int64_t>::max()), span)
446	      << "Packed 4-bit slice byte offset overflows int64";
447	  return std::make_shared<ConstInt>(static_cast<int64_t>(*byte_offset), DataType::INDEX, Span::unknown());
448	}
449	
450	/// Compute additional byte offset for a view operation.
451	/// Dispatches: slice ops → stride-based offset, others → zero offset.
452	inline ExprPtr ComputeViewByteOffset(const CallPtr& call, const TypePtr& parent_type) {
453	  const std::string& op_name = call->op_->name_;
454	
455	  if (IsOp(call, "tensor.slice") || IsOp(call, "tile.slice")) {
456	    auto shaped = std::dynamic_pointer_cast<const ShapedType>(parent_type);
457	    INTERNAL_CHECK_SPAN(shaped, call->span_) << "Internal error: slice parent must be ShapedType";
458	
459	    // tensor.slice(input, shape, offset) → offset is args[2]
460	    // tile.slice(input, shape, offset[, valid_shape]) → offset is args[2]
461	    size_t offset_arg_idx = 2;
462	    INTERNAL_CHECK_SPAN(offset_arg_idx < call->args_.size(), call->span_)
463	        << "Internal error: " << op_name << " missing offset argument";
464	
465	    // Extract individual offset elements from the MakeTuple expression
466	    std::vector<ExprPtr> offsets;
467	    if (auto make_tuple = As<MakeTuple>(call->args_[offset_arg_idx])) {
468	      offsets = make_tuple->elements_;
469	    } else {
470	      offsets.push_back(call->args_[offset_arg_idx]);
471	    }
472	
473	    return ComputeSliceByteOffset(offsets, shaped->shape_, shaped->dtype_, call->span_);
474	  }
475	
476	  // Non-slice view ops (reshape, transpose, extract):
477	  // No additional byte offset — same memory region, different interpretation
478	  return MakeZeroByteOffset();
479	}
480	
481	}  // namespace pypto::ir
482	
483	#endif  // PYPTO_IR_TRANSFORMS_UTILS_MEMREF_UTILS_H_
