2773	class YieldFixupMutator : public IRMutator {
2774	 public:
2775	  YieldFixupMutator() = default;
2776	
2777	  /// `fixup_if_stmts=false` reconciles only ForStmt carries. Used under
2778	  /// memory_planner=PtoAS, where PTO codegen already re-points a branch-local
2779	  /// producer at the phi handle (#1956/#1985) and copies in anything it declines
2780	  /// to re-point — a copy-free path that an IR-level `tile.move` would displace
2781	  /// with an extra buffer plus a `pto.tmov`. Loop carries have no such codegen
2782	  /// path, so they still need the move.
2783	  explicit YieldFixupMutator(bool fixup_if_stmts) : fixup_if_stmts_(fixup_if_stmts) {}
2784	
2785	  StmtPtr VisitStmt_(const ForStmtPtr& op) override {
2786	    // First recurse into nested control flow
2787	    auto result = IRMutator::VisitStmt_(op);
2788	    auto for_stmt = As<ForStmt>(result);
2789	    if (!for_stmt || for_stmt->iter_args_.empty()) return result;
2790	
2791	    auto yield_stmt = FindYieldStmt(for_stmt->body_);
2792	    if (!yield_stmt) return result;
2793	
2794	    // Check each (iter_arg, yield_value) pair for MemRef mismatch.
2795	    // Use initValue's MemRef as the target because codegen maps iter_arg to initValue's buffer,
2796	    // and MemoryReuse may have updated initValue's MemRef without updating iter_arg's.
2797	    // One index over the carry buffers serves both the overlap rejection below
2798	    // and the conflict graph in OrderCarryCopies.
2799	    const std::vector<MemRefPtr> carry_ranges = CollectCarryRanges(for_stmt);
2800	    const CarryRangeIndex carry_index(carry_ranges);
