2852	    if (copies.empty()) {
2853	      // Even without tile.move insertion, iter_arg and return_var may have stale MemRefs
2854	      // (MemoryReuse updates initValue/yield but not iter_arg/return_var types).
2855	      // Ensure all 4 loop-carry variables share the same MemRef (= initValue's).
