2994	  /// One reconciling copy for one loop carry: `dst_memref <- source`.
2995	  struct CarryCopy {
2996	    size_t index;                           ///< iter_arg / yield position
2997	    VarPtr source;                          ///< what the copy reads
2998	    VarPtr moved_var;                       ///< the copy's LHS, replacing the yield value
2999	    StmtPtr move_stmt;                      ///< the `tile.move` itself
3000	    MemRefPtr src_memref;                   ///< byte range the copy reads
