3008	  /// Byte ranges grouped by allocation, so overlap questions are index lookups
3009	  /// rather than all-pairs scans.
3010	  ///
3011	  /// Within an allocation the constant-offset ranges are sorted by start, which
3012	  /// makes both users linear-after-sort: the pairwise-overlap check only has to
3013	  /// compare neighbours (sorted by start, if any two ranges overlap then some
3014	  /// adjacent pair does), and a query binary-searches to its first candidate and
3015	  /// stops at the first range past its end. A range whose offset is not constant
3016	  /// has no position on that axis, so it is kept aside and treated as touching
3017	  /// everything in its allocation — the same conservative answer
3018	  /// `MemRef::MayAlias` gives.
3019	  class CarryRangeIndex {
3020	   public:
3021	    /// `ranges[i]` is the byte range owned by carry `i`; a null entry is skipped.
3022	    explicit CarryRangeIndex(const std::vector<MemRefPtr>& ranges) {
3023	      for (size_t i = 0; i < ranges.size(); ++i) {
3024	        if (!ranges[i]) continue;
3025	        const Var* base = ranges[i]->base_.get();
3026	        auto offset = As<ConstInt>(ranges[i]->byte_offset_);
3027	        if (!offset) {
3028	          unpositioned_[base].push_back(i);
3029	          continue;
3030	        }
3031	        const int64_t begin = offset->value_;
3032	        positioned_[base].push_back(Entry{begin, RangeEnd(begin, ranges[i]->size_, ranges[i]->span_), i});
3033	      }
3034	      for (auto& [base, entries] : positioned_) {
3035	        static_cast<void>(base);
3036	        std::sort(entries.begin(), entries.end(),
3037	                  [](const Entry& a, const Entry& b) { return a.begin < b.begin; });
3038	      }
3039	    }
3040	
3041	    /// Call `fn(i)` for every indexed range that may overlap `query`.
3042	    template <typename Fn>
3043	    void ForEachOverlapping(const MemRefPtr& query, const Fn& fn) const {
3044	      const Var* base = query->base_.get();
3045	      if (auto loose = unpositioned_.find(base); loose != unpositioned_.end()) {
3046	        for (size_t i : loose->second) fn(i);
3047	      }
3048	      auto bucket = positioned_.find(base);
3049	      if (bucket == positioned_.end()) return;
3050	      const auto& entries = bucket->second;
3051	
3052	      auto offset = As<ConstInt>(query->byte_offset_);
3053	      if (!offset) {  // unknown position — conservatively touches the whole allocation
3054	        for (const Entry& entry : entries) fn(entry.index);
3055	        return;
3056	      }
3057	      const int64_t begin = offset->value_;
3058	      const int64_t end = RangeEnd(begin, query->size_, query->span_);
3059	      // Entries are sorted by start, so the first candidate is the first one
3060	      // starting at or after `begin`, less the single earlier one that may still
3061	      // cover `begin`.
3062	      auto it = std::lower_bound(entries.begin(), entries.end(), begin,
3063	                                 [](const Entry& entry, int64_t value) { return entry.begin < value; });
3064	      if (it != entries.begin() && std::prev(it)->end > begin) --it;
3065	      for (; it != entries.end() && it->begin < end; ++it) {
3066	        if (it->end > begin) fn(it->index);
3067	      }
3068	    }
3069	
3070	    /// Every pair of indexed ranges that overlaps, as (lower index, higher index).
3071	    [[nodiscard]] std::vector<std::pair<size_t, size_t>> OverlappingPairs() const {
3072	      std::vector<std::pair<size_t, size_t>> pairs;
3073	      for (const auto& [base, entries] : positioned_) {
3074	        for (size_t n = 1; n < entries.size(); ++n) {
3075	          if (entries[n].begin < entries[n - 1].end) {
3076	            pairs.emplace_back(std::minmax(entries[n - 1].index, entries[n].index));
3077	          }
3078	        }
3079	        // An unpositioned range conservatively covers its whole allocation, so it
3080	        // conflicts with every other range there. One witness is enough to report.
3081	        auto loose = unpositioned_.find(base);
3082	        if (loose != unpositioned_.end() && !entries.empty()) {
3083	          pairs.emplace_back(std::minmax(loose->second.front(), entries.front().index));
3084	        }
3085	      }
3086	      for (const auto& [base, loose] : unpositioned_) {
3087	        static_cast<void>(base);
3088	        if (loose.size() > 1) pairs.emplace_back(std::minmax(loose[0], loose[1]));
3089	      }
3090	      return pairs;
3091	    }
3092	
3093	   private:
3094	    struct Entry {
3095	      int64_t begin;
3096	      int64_t end;
3097	      size_t index;
3098	    };
3099	
3100	    /// One past the last byte of `[begin, begin + size)`, as a signed offset.
3101	    ///
3102	    /// `MemRef::size_` is unsigned and the interval arithmetic below is signed,
3103	    /// so a size past `INT64_MAX` or a sum that wraps would silently corrupt both
3104	    /// the sort order and every overlap answer derived from it. No on-chip buffer
3105	    /// comes anywhere near that, so a violation is a corrupt MemRef rather than
3106	    /// something to accommodate.
3107	    static int64_t RangeEnd(int64_t begin, uint64_t size, const Span& span) {
3108	      constexpr auto kMax = std::numeric_limits<int64_t>::max();
3109	      INTERNAL_CHECK_SPAN(size <= static_cast<uint64_t>(kMax), span)
3110	          << "Internal error: MemRef size " << size << " does not fit a signed byte offset";
3111	      const auto signed_size = static_cast<int64_t>(size);
3112	      INTERNAL_CHECK_SPAN(begin <= kMax - signed_size, span)
3113	          << "Internal error: MemRef byte range [" << begin << ", +" << size << ") overflows";
3114	      return begin + signed_size;
3115	    }
3116	    std::map<const Var*, std::vector<Entry>> positioned_;
3117	    std::map<const Var*, std::vector<size_t>> unpositioned_;
3118	  };
