3120	  /// The byte range each carry owns, indexed by iter_arg position (null when the
3121	  /// carry is not a tile with a MemRef).
3122	  static std::vector<MemRefPtr> CollectCarryRanges(const ForStmtPtr& for_stmt) {
3123	    std::vector<MemRefPtr> ranges(for_stmt->iter_args_.size());
3124	    for (size_t i = 0; i < for_stmt->iter_args_.size(); ++i) {
3125	      // AsVarLike: a nested loop seeds its carries from the enclosing loop's
3126	      // IterArg, which As<Var> would skip -- and skipping it is exactly how two
3127	      // nested carries seeded from one outer carry would slip past the check below.
3128	      auto init_var = AsVarLike(for_stmt->iter_args_[i]->initValue_);
