3153	          << for_stmt->iter_args_[rhs]->name_hint_
3154	          << "' share the same on-chip buffer, so one iteration cannot preserve both. Give each "
3155	             "loop-carried tile its own initial value -- build them with separate ops instead of "
3156	             "seeding both from the same tile.";
3157	    }
3158	  }
