3589	/// Reconcile bare-Var SSA identity copies whose LHS/RHS buffers diverged.
3590	///
3591	/// An AssignStmt whose value is a bare Var (`x = y`, not a Call) is a pure SSA
3592	/// rename — `x` must alias `y`'s buffer.  CoalesceAccumulatorIfPhis retargets an
3593	/// if-phi's producers + return_var onto the accumulator buffer, which can leave a
3594	/// downstream copy of the (now-moved) return_var still typed on the old buffer:
3595	///   c: Tile[..., mem_acc_17] = c_phi_2   // c_phi_2 was retargeted to mem_acc_5
3596	/// Codegen would then store from the stale buffer.  This single forward pass
3597	/// retypes every such copy's LHS to its RHS's MemRef and substitutes the LHS's
3598	/// downstream uses, so the whole rename chain follows.  A no-op when no identity
3599	/// copy has a buffer mismatch (the common case).
3600	class NormalizeIdentityCopyBuffersMutator : public IRMutator {
3601	 public:
3602	  ExprPtr VisitExpr_(const VarPtr& op) override {
3603	    auto it = subst_.find(op);
3604	    return it != subst_.end() ? it->second : op;
3605	  }
3606	
3607	  StmtPtr VisitStmt_(const AssignStmtPtr& op) override {
3608	    // Only bare-Var identity copies are pure renames; Call producers are not.
3609	    auto src_var = AsVarLike(op->value_);
3610	    if (src_var) {
3611	      auto new_src = AsVarLike(VisitExpr(op->value_));  // follow prior substitutions
3612	      auto lhs_tile = new_src ? GetTileTypeWithMemRef(op->var_->GetType()) : nullptr;
3613	      auto rhs_tile = new_src ? GetTileTypeWithMemRef(new_src->GetType()) : nullptr;
3614	      if (lhs_tile && rhs_tile &&
3615	          !MemRef::SameAllocation(GetDefinedMemRef(lhs_tile), GetDefinedMemRef(rhs_tile))) {
3616	        auto new_lhs = std::make_shared<Var>(op->var_->name_hint_, new_src->GetType(), op->var_->span_);
3617	        subst_[op->var_] = new_lhs;
3618	        return std::make_shared<AssignStmt>(new_lhs, new_src, op->span_);
3619	      }
3620	    }
3621	    // An in-place accumulator Call (GetOutputReusesInputArg, e.g. tile.matmul_acc)
3622	    // is not a bare rename, but its output MemRef aliases its reused input's. When
3623	    // the coalescing retargeted that input onto another buffer (its bare-copy chain
3624	    // retyped in subst_ above), the Call's output must follow — else it is left
3625	    // declared on the now-orphaned original buffer that nothing writes, and
3626	    // downstream reads of this output address a stale, never-written buffer (the
3627	    // non-divisor K-peel matmul_acc tail after CoalesceAccumulatorIfPhis).
3628	    if (auto reanchored = ReanchorInplaceOutput(op)) return reanchored;
3629	    return IRMutator::VisitStmt_(op);
3630	  }
3631	
3632	 private:
3633	  /// Re-anchor an in-place op's output onto its reused input's new buffer when the
3634	  /// input was retargeted, preserving the output's tile metadata (shape/dtype/space)
3635	  /// and swapping only the MemRef.  Returns nullptr when not applicable.
3636	  StmtPtr ReanchorInplaceOutput(const AssignStmtPtr& op) {
3637	    auto call = As<Call>(op->value_);
3638	    if (!call) return nullptr;
3639	    const auto& reg = OpRegistry::GetInstance();
3640	    if (!reg.IsRegistered(call->op_->name_)) return nullptr;
3641	    auto reuse_idx = reg.GetEntry(call->op_->name_).GetOutputReusesInputArg();
3642	    if (!reuse_idx.has_value() || *reuse_idx >= call->args_.size()) return nullptr;
3643	    auto in_var = AsVarLike(call->args_[*reuse_idx]);
3644	    if (!in_var) return nullptr;
3645	    auto new_in = AsVarLike(VisitExpr(in_var));                   // follow prior subst_ renames
3646	    if (!new_in || new_in.get() == in_var.get()) return nullptr;  // input not moved
3647	    auto lhs_tile = GetTileTypeWithMemRef(op->var_->GetType());
3648	    auto in_old_tile = GetTileTypeWithMemRef(in_var->GetType());
3649	    auto in_new_tile = GetTileTypeWithMemRef(new_in->GetType());
3650	    if (!lhs_tile || !in_old_tile || !in_new_tile) return nullptr;
3651	    // Fire only when the output aliased the input in-place AND the input moved.
3652	    if (!MemRef::SameAllocation(GetDefinedMemRef(lhs_tile), GetDefinedMemRef(in_old_tile)) ||
3653	        MemRef::SameAllocation(GetDefinedMemRef(in_new_tile), GetDefinedMemRef(in_old_tile))) {
3654	      return nullptr;
3655	    }
3656	    auto new_type = CloneTypeWithMemRef(op->var_->GetType(), GetDefinedMemRef(in_new_tile),
3657	                                        in_new_tile->GetMemorySpace());
3658	    auto new_lhs = std::make_shared<Var>(op->var_->name_hint_, new_type, op->var_->span_);
3659	    subst_[op->var_] = new_lhs;
3660	    auto recursed = As<AssignStmt>(IRMutator::VisitStmt_(op));
3661	    INTERNAL_CHECK_SPAN(recursed, op->span_) << "Internal error: AssignStmt visit must yield an AssignStmt";
3662	    return std::make_shared<AssignStmt>(new_lhs, recursed->value_, recursed->span_);
3663	  }
3664	
3665	  std::map<VarPtr, ExprPtr> subst_;
3666	};
