3685	// while MemoryReuse is skipped, so codegen can emit a shared tile_buf handle for
3686	// the must-alias buffers and ptoas PlanMemory does the reuse.
3687	FunctionPtr TransformMaterializeSemanticAliases(const FunctionPtr& func) {
3688	  INTERNAL_CHECK(func) << "MaterializeSemanticAliases cannot run on null function";
3689	
3690	  // Orchestration functions submit tasks and never hold TileType variables.
3691	  if (func->func_type_ == FunctionType::Orchestration) return func;
3692	
