3694	  TopDownRetargeter retargeter;
3695	  auto rewrites = retargeter.Compute(new_body);
3696	  if (!rewrites.empty()) {
3697	    RetypeApplier applier(std::move(rewrites));
3698	    new_body = applier.VisitStmt(new_body);
