3743	  if (new_body == func->body_) return func;
3744	
3745	  return std::make_shared<const Function>(func->name_, func->params_, func->param_directions_,
3746	                                          func->return_types_, new_body, func->span_, func->func_type_,
3747	                                          func->level_, func->role_, func->attrs_);
3748	}
