3801	      analysis_result.lifetimes, hazard, forbid_alias, analysis_result.phi_family_ids,
3802	      analysis_result.var_sharing_groups, analysis_result.var_liveness, analysis_result.pipeline_membership,
3803	      analysis_result.pipeline_load_tiles, reserved_end_by_space, pinned_bases, func, &hints);
