333	std::vector<std::pair<const MemRef*, MemRefPtr>> AllocateMemoryAddresses(
334	    const std::vector<MemRefWithSpace>& memrefs, const ReserveBufferResolution& reserve_resolution,
335	    const MemoryAllocatorPolicy& policy, const std::map<const Var*, uint64_t>& pinned_alloc_sizes,
336	    const std::string& func_name) {
337	  const ReservedEndBySpace& reserved_end_by_space = reserve_resolution.reserved_end_by_space;
338	  // Group MemRefs by memory space
339	  std::unordered_map<MemorySpace, std::vector<MemRefPtr>> space_to_memrefs;
340	  for (const auto& [memref, memory_space] : memrefs) {
341	    space_to_memrefs[memory_space].push_back(memref);
342	  }
343	
344	  // Create new MemRefs with allocated addresses for each memory space
345	  std::vector<std::pair<const MemRef*, MemRefPtr>> memref_pairs;
346	
347	  for (auto& [space, refs] : space_to_memrefs) {
348	    if (!policy.ShouldAllocate(space)) {
349	      continue;
350	    }
351	
352	    policy.OrderMemRefs(refs);
353	
354	    // Group MemRefs by base_ Ptr identity.  base_order preserves the policy's
355	    // sort order via the first MemRef that introduces each base.
356	    std::map<const Var*, std::vector<MemRefPtr>> base_groups;
357	    std::vector<const Var*> base_order;
358	    for (const auto& ref : refs) {
359	      const Var* base_key = ref->base_.get();
360	      auto inserted = base_groups.try_emplace(base_key);
361	      if (inserted.second) base_order.push_back(base_key);
362	      inserted.first->second.push_back(ref);
363	    }
364	
365	    // The ordering + alignment bump walk lives in SpaceFootprint, shared with MemoryReuse's
366	    // capacity fit check so the two footprints are identical by construction (#1475).
367	    uint64_t reserved_start = 0;
368	    auto reserved_it = reserved_end_by_space.find(space);
369	    if (reserved_it != reserved_end_by_space.end()) {
370	      reserved_start = reserved_it->second;
371	    }
372	    SpaceFootprint footprint(space, policy, reserved_start);
373	    for (const Var* base_key : base_order) {
374	      const auto& group = base_groups.at(base_key);
375	
376	      // Slot size = max member.size_.  The root MemRef (byte_offset == 0) is
377	      // sized to the full alloc; views are sub-regions and never exceed it.
378	      uint64_t slot_size = 0;
379	      for (const auto& ref : group) {
380	        INTERNAL_CHECK_SPAN(ref->size_ > 0, ref->span_)
381	            << "AllocateMemoryAddr encountered zero-sized MemRef '" << ref->name_hint_
382	            << "'. InitMemRef should reject dynamic or invalid allocation shapes before address assignment.";
383	        slot_size = std::max(slot_size, static_cast<uint64_t>(ref->size_));
384	      }
385	      // A declared allocation reserves what its alloc statement says, which for a
386	      // multi-slot declaration exceeds any single member. Everything else is sized
387	      // by its largest member, as before.
388	      uint64_t buffer_size = slot_size;
389	      auto declared_size = pinned_alloc_sizes.find(base_key);
390	      if (declared_size != pinned_alloc_sizes.end()) {
391	        buffer_size = std::max(buffer_size, declared_size->second);
392	      }
393	      // Reserve this base-group's physical buffer; base_addr is where its members land.
394	      const uint64_t base_addr = footprint.OpenBuffer(buffer_size);
395	
396	      // Bump the whole group to `current_addr`, then preserve each member's
397	      // own offset within the slot: new byte_offset = base_addr + old offset.
398	      //
399	      // InitMemRef already records each view's relative offset (parent offset +
400	      // the view op's byte offset, see ShareMemRefFrom).  The root MemRef has
401	      // offset 0, so it lands on base_addr; a ``tile.slice`` view at row k lands
402	      // on base_addr + k*row_stride.  Codegen reads ``pto.alloc_tile`` addr 1:1
403	      // from this ConstInt, so a reshape-of-slice chain — whose result inherits
404	      // the slice's offset but does NOT go through ``pto.subview`` — gets the
405	      // correct per-view address instead of collapsing onto the parent base
406	      // (issue #1510).  Pure ``tile.slice`` codegen is unaffected: it still
407	      // derives the offset from the slice op's own operands off the root base.
408	      for (const auto& old_memref : group) {
409	        // Fold a const relative offset into a single ConstInt: base + offset.
410	        // A reshape-of-slice chain inherits the slice's offset but does NOT go
411	        // through `pto.subview`, so its address must come from this MemRef
412	        // (issue #1510).
413	        //
414	        // A *dynamic* offset cannot fold. For a declared allocation the address
415	        // becomes the expression `base_addr + offset` and codegen lowers it into
416	        // the tile's runtime address assignment — that is how a runtime slot index
417	        // (`l0c[i % 2]`, scaled to a byte offset by InitMemRef) reaches the
418	        // hardware. Dropping it would silently address slot 0 every iteration.
419	        //
420	        // Every OTHER dynamic offset keeps the old behaviour: fall back to the
421	        // bare base. Those are `tile.slice` views, which reach codegen through
422	        // `pto.subview` and re-derive their offset from the slice op's own
423	        // operands, so this address is unused — and emitting the expression anyway
424	        // is actively harmful: it is not renderable at the `pto.alloc_tile addr`
425	        // position and PTOAS rejects the module with "expected SSA operand".
426	        //
427	        // INT64 dtype is required by the PTOAS dialect's `pto.alloc_tile` addr
428	        // operand; PTO codegen reads this dtype from the ConstInt 1:1.
429	        ExprPtr member_addr_expr;
430	        auto old_offset = std::dynamic_pointer_cast<const ConstInt>(old_memref->byte_offset_);
431	        if (!old_offset && pinned_alloc_sizes.count(old_memref->base_.get()) == 0) {
432	          // Not a declared allocation: bare base, exactly as before slots existed.
433	          old_offset = std::make_shared<ConstInt>(0, DataType::INT64, Span::unknown());
434	        }
435	        if (old_offset) {
436	          member_addr_expr = std::make_shared<ConstInt>(static_cast<int64_t>(base_addr) + old_offset->value_,
437	                                                        DataType::INT64, Span::unknown());
438	        } else {
439	          auto base_expr =
440	              std::make_shared<ConstInt>(static_cast<int64_t>(base_addr), DataType::INDEX, Span::unknown());
441	          member_addr_expr =
442	              std::make_shared<Add>(base_expr, old_memref->byte_offset_, DataType::INDEX, Span::unknown());
443	        }
444	        // NOTE: MemRef is identity-bearing — each result must get a fresh
445	        // unique_id_, so build it via the explicit constructor (MutableCopy is
446	        // static_assert-forbidden for Var/MemRef).
447	        auto new_memref = std::make_shared<MemRef>(
448	            old_memref->name_hint_, old_memref->base_, member_addr_expr, old_memref->size_, old_memref->span_,
449	            old_memref->is_pinned_, old_memref->slot_count_, old_memref->slot_index_);
450	        memref_pairs.emplace_back(old_memref.get(), new_memref);
451	      }
452	    }
453	
454	    // Capacity is checked HERE because this is the only place the number is exact.
455	    // The footprint is built from each buffer'strue reserved size, so it counts a
456	    // declared allocation's unbound slots and does not depend on any tile's address
457	    // being constant. Reconstructing it downstream from the addressed tiles cannot
458	    // do either: a slot nobody binds leaves no MemRef to see, and a runtime slot
459	    // index leaves no constant to add up.
460	    if (backend::BackendConfig::IsConfigured()) {
461	      const uint64_t limit = backend::GetBackend()->GetMemSize(space);
462	      const uint64_t used = footprint.HighWater();
463	      CHECK(limit == 0 || used <= limit)
464	          << MemorySpaceToString(space) << " buffer usage (" << used << " bytes) exceeds platform limit ("
465	          << limit << " bytes)" << ReservedBytesNote(reserve_resolution, space, func_name);
466	    }
467	  }
468	
469	  // Sort by byte_offset (ascending order) so alloc statements are in address order.
470	  //
471	  // Comparing by offset only when *both* sides are constant, and by name
472	  // otherwise, is not a strict weak ordering once dynamic offsets are reachable:
473	  // with A=(name "z", offset 0), B=(name "a", offset 1) and C=(name "m", dynamic),
474	  // A < B by offset and B < C by name, yet A < C is false — and a non-transitive
475	  // comparator makes std::sort undefined behaviour. A declared allocation's
476	  // runtime slot index made that case reachable.
477	  //
478	  // Ordering on one total key instead: constants first in address order, then
479	  // dynamic addresses by name. `name_hint_` breaks ties among equal offsets so
480	  // the result is deterministic (two MemRefs of one base group can share an
481	  // offset, e.g. a view over its parent).
482	  std::sort(memref_pairs.begin(), memref_pairs.end(),
483	            [](const std::pair<const MemRef*, MemRefPtr>& a, const std::pair<const MemRef*, MemRefPtr>& b) {
484	              auto off_a = std::dynamic_pointer_cast<const ConstInt>(a.second->byte_offset_);
485	              auto off_b = std::dynamic_pointer_cast<const ConstInt>(b.second->byte_offset_);
486	              if (static_cast<bool>(off_a) != static_cast<bool>(off_b)) {
487	                return static_cast<bool>(off_a);  // constants before dynamic
488	              }
489	              if (off_a && off_b && off_a->value_ != off_b->value_) {
490	                return off_a->value_ < off_b->value_;
491	              }
492	              return a.second->name_hint_ < b.second->name_hint_;
493	            });
494	
495	  return memref_pairs;
496	}
